export const flashcards = Object.entries(cardsByCp).flatMap(([cp, rows]) =>
  rows.map(([question, answer, detail, tags], index) => ({
    id: `${cp}-c${String(index + 1).padStart(2, "0")}`,
    cp, question, answer, detail, tags
  }))
);

export const contentSources = Object.values(references);

// Cas créés pour appliquer les définitions, avec toutes les données nécessaires.
const foundationExercises = {
  cp1: { prompt: "Une API utilise Node.js et PostgreSQL. Après npm install, l’erreur est ECONNREFUSED sur le port de la base. Quel outil manque probablement, et pourquoi les dépendances npm ne suffisent-elles pas ?", answer: "PostgreSQL doit être démarré et joignable à l’adresse configurée. npm installe les paquets JavaScript ; il ne lance pas automatiquement le SGBD. Vérifier service, adresse, port et variables, une hypothèse à la fois." },
  cp2: { prompt: "Une page propose Voir le catalogue (ouvre /catalogue) et Ajouter au panier (modifie le panier sur place). Choisis a ou button pour chaque élément et explique pourquoi.", answer: "Voir le catalogue : un lien a avec href, car il navigue. Ajouter au panier : un button, car il déclenche une action. Les éléments natifs apportent la sémantique et les interactions clavier appropriées." },
  cp3: { prompt: "Stock initial : 2. Une commande demande 3 unités. Quelle décision le service métier prend-il ? Quel stock doit-on retrouver après le refus ?", answer: "Il refuse la commande car 3 dépasse le stock disponible. Le stock reste à 2. Les entrées sont stock=2 et quantité=3 ; le résultat est un refus sans modification. Tester aussi quantité=2 et une quantité invalide." },
  cp4: { prompt: "L’objectif d’un Sprint est de rendre la recherche de livres utilisable. Le formulaire est terminé, mais la requête ne fonctionne pas. Peut-on dire que l’objectif est atteint ? Quelle information partager ?", answer: "Non : un écran seul ne rend pas la recherche utilisable. Rendre visible le blocage de la requête, son impact sur l’objectif, l’aide nécessaire et le travail restant. Adapter le plan tout en gardant l’objectif comme repère." },
  cp5: { prompt: "Une bibliothèque demande un champ de recherche. Reformule son besoin en user story pour un lecteur qui connaît une partie du titre, puis donne un critère d’acceptation vérifiable.", answer: "En tant que lecteur, je souhaite chercher par une partie du titre afin de trouver le livre à emprunter. Critère : étant donné un catalogue contenant Le Petit Prince, quand je cherche Petit, alors Le Petit Prince apparaît. Une recherche sans correspondance affiche Aucun livre trouvé." },
  cp6: { prompt: "Pour GET /livres/7, il faut lire un identifiant HTTP, décider si le livre est visible et exécuter SELECT. Attribue chaque tâche à contrôleur, service ou repository.", answer: "Le contrôleur lit et valide la forme de l’identifiant HTTP puis construit la réponse. Le service applique la règle de visibilité. Le repository exécute la requête paramétrée. Ce découpage est un exemple de répartition des responsabilités, pas une obligation de dossiers portant ces noms." },
  cp7: { prompt: "Règles : un auteur peut n’avoir écrit aucun livre ; un livre du catalogue possède au moins un auteur ; plusieurs auteurs peuvent coécrire et chacun écrire plusieurs livres. Quelles cardinalités et quelles tables proposer ?", answer: "AUTEUR (0,n) — ÉCRIRE — (1,n) LIVRE. Tables AUTEUR(id, nom), LIVRE(id, titre), ECRITURE(auteur_id, livre_id), avec clé composée et deux clés étrangères. L’obligation pour chaque livre d’avoir au moins un auteur doit aussi être assurée : les seules clés étrangères dans ECRITURE ne la garantissent pas." },
  cp8: { prompt: "La table livre contient id et titre. Un utilisateur fournit l’identifiant texte 7 OR 1=1. Pourquoi SELECT ... WHERE id = $1 avec cette entrée en paramètre est-il différent d’une concaténation dans la requête ?", answer: "Le paramètre reste une valeur ; il ne devient pas un opérateur SQL. Pour une colonne entière, l’entrée doit être refusée par la validation ou le typage de la base. La concaténation peut transformer OR 1=1 en code SQL et élargir le résultat. Conserver validation et requête paramétrée." },
  cp9: { prompt: "Test A appelle total([2,3]) avec toutes ses dépendances simulées. Test B insère une ligne dans une vraie base de test puis appelle le repository pour la relire. Quel test est unitaire, quel test est d’intégration, et qu’ajoute B ?", answer: "A vise une unité isolée : test unitaire. B vérifie la coopération entre le repository et le SGBD : test d’intégration. B peut détecter une erreur SQL, de mapping ou de contrainte que les doubles de test de A ne révéleraient pas." },
  cp10: { prompt: "L’ancienne API ne lit que livre.titre. La nouvelle lit aussi livre.resume. Propose un ordre de déploiement évitant une requête sur une colonne absente.", answer: "Tester la migration et sauvegarder selon la procédure ; ajouter resume de manière compatible avec l’ancienne API ; déployer la nouvelle version ; exécuter les contrôles. Supprimer une ancienne colonne demande une étape distincte après vérification des consommateurs. Le rollback doit considérer code et schéma." },
  cp11: { prompt: "Le pipeline a trois jobs : tests, build (dépend de tests), déploiement (dépend de build). tests est rouge. Quels jobs peuvent avancer et que faut-il examiner ?", answer: "Avec ces dépendances et sans condition spéciale, build puis déploiement sont bloqués. Lire la première erreur du job tests, reproduire le contexte, corriger et relancer les contrôles. Supprimer l’assertion pour obtenir du vert ne résout pas le défaut." },
};
for (const cp of competencies) {
  cp.sections[0].exercise = foundationExercises[cp.id];
}

for (const cp of competencies) {
  cp.sections.forEach((section, index) => { section.sources = competencyReferences[cp.id][index]; });
}
const baseLessonIndices = {
  cp1: [0,1,1,2,2,2,3,0,3,3], cp2: [0,1,1,0,0,2,2,3,3,1,2,1],
  cp3: [0,0,0,1,1,1,2,2,2,4,4,4], cp4: [0,0,0,1,1,1,2,3,2,3],
  cp5: [0,0,1,1,1,1,2,2,3,3], cp6: [0,0,2,2,1,1,1,2,3,1,3,3],
  cp7: [0,0,1,1,1,1,2,2,2,3], cp8: [0,0,1,1,1,1,1,2,2,2,3,3],
  cp9: [0,0,2,1,1,2,2,3,3,0], cp10: [0,1,1,1,2,3,3,3,3,0],
  cp11: [0,0,0,1,1,2,2,3,3,3],
};
for (const card of flashcards) {
  const index = Number(card.id.split('-c')[1]) - 1;
  card.lessonIndex = baseLessonIndices[card.cp][index];
  if (['cp6-c11', 'cp6-c12'].includes(card.id)) card.lessonCp = 'cp3';
  const key = cardReferences[card.cp][index];
  card.sources = key ? [].concat(key).map(name => references[name]).filter(Boolean) : [];
}
for (const [id, lessonIndex] of [['cp7-c01', 9], ['cp7-c02', 11], ['cp7-c06', 17]]) {
  const card = flashcards.find(item => item.id === id);
  card.lessonTechnology = 'merise';
  card.lessonIndex = lessonIndex;
}
// La progression Merise donne les références académiques de la modélisation.
const meriseSources = courseSections.filter(item => item.technology === 'merise').flatMap(item => item.section.sources || []);
const meriseModelSources = [...new Map(meriseSources.filter(source => /mocodo|merise-slides/i.test(source.url)).map(source => [source.url, source])).values()];
const normalFormSources = [...new Map(meriseSources.filter(source => /nor1|normalization/i.test(source.url)).map(source => [source.url, source])).values()];
const cp7 = competencies.find(cp => cp.id === 'cp7');
cp7.sections[0].sources = meriseModelSources;
cp7.sections[1].sources.push(...normalFormSources);
for (const card of flashcards.filter(card => !card.sources.length)) card.sources = card.id === 'cp7-c06' ? normalFormSources : meriseModelSources;

// Les identifiants initiaux restent stables pour conserver le planning existant.
for (const item of courseSections) {
  const competency = competencies.find(cp => cp.id === item.cp);
  if (!competency) throw new Error(`Compétence inconnue : ${item.cp}`);
  competency.sections.push({ ...item.section, course: true, technology: item.technology });
}
flashcards.push(...courseCards);
